import { words, groupBy } from 'es-toolkit';
import { truncate } from 'es-toolkit/compat';

export interface Row {
  id: number;
  name: string;
  age: number;
}

export type Config = Record<string, unknown>;

export function tokens(text: string): string[] {
  return words(text);
}

export function byAge(rows: Row[]): Record<string, Row[]> {
  return groupBy(rows, r => r.age);
}

export function preview(text: string): string {
  return truncate(text, { length: 24 });
}
EOF
npm run size -- out/module.ts 2>&1 | tail -2; npm run size -- src/module.ts 2>&1 | tail -2
cat > $TEMP/t.mjs <<'EOF'
import {words as a} from 'es-toolkit'; import {words as b} from 'es-toolkit/compat';
const cs='aA1 -_.Zb';let bad=0;
for(let i=0;i<200000;i++){let s='';const n=Math.random()*12|0;for(let j=0;j<n;j++)s+=cs[Math.random()*cs.length|0];
if(JSON.stringify(a(s))!==JSON.stringify(b(s))){if(bad++<5)console.log(JSON.stringify(s),a(s),b(s));}}
console.log('bad',bad);
EOF
cp $TEMP/t.mjs ./t.mjs && node t.mjs; rm t.mjs
npx tsc --noEmit -p . 2>&1 | tail -5

